    a = ((uint32)(uint16)matrix.m[0][0] | ((uint32)(uint16)matrix.m[0][1] << 16));
    b = ((uint32)(uint16)matrix.m[0][2] | ((uint32)(uint16)matrix.m[1][0] << 16));
    c = ((uint32)(uint16)matrix.m[1][1] | ((uint32)(uint16)matrix.m[1][2] << 16));
    d = ((uint32)(uint16)matrix.m[2][0] | ((uint32)(uint16)matrix.m[2][1] << 16));
    e = ((uint16)matrix.m[2][2]);
    SetRotMatrix(&matrix);
    game_rotate_vector_current_gte(forward);
    game_rotate_vector_current_gte(side);
    game_build_vector_rotation(&matrix, native_angles);
    a = ((uint32)(uint16)matrix.m[0][0] | ((uint32)(uint16)matrix.m[0][1] << 16));
    b = ((uint32)(uint16)matrix.m[0][2] | ((uint32)(uint16)matrix.m[1][0] << 16));
    c = ((uint32)(uint16)matrix.m[1][1] | ((uint32)(uint16)matrix.m[1][2] << 16));
    d = ((uint32)(uint16)matrix.m[2][0] | ((uint32)(uint16)matrix.m[2][1] << 16));
    e = ((uint16)matrix.m[2][2]);
    SetRotMatrix(&matrix);
    game_rotate_vector_current_gte(forward);
    game_rotate_vector_current_gte(side);
    a = ((sint32)(0 - forward[1]) >> 4);
    side[0] = ((sint32)side[0] >> 4);
    side[2] = ((sint32)side[2] >> 4);
    side[1] = ((sint32)side[1] >> 4);
    pitch = game_angle_asin(a);
    value = game_vector_atan2(0 - forward[0], forward[2]);
    yaw = 0 - value;
    local_angles[0] = (0 - pitch);
    local_angles[1] = value;
    local_angles[2] = 0;
    game_build_alternate_rotation_via_gte(&matrix, local_angles);
    a = ((uint32)(uint16)matrix.m[0][0] | ((uint32)(uint16)matrix.m[0][1] << 16));
    b = ((uint32)(uint16)matrix.m[0][2] | ((uint32)(uint16)matrix.m[1][0] << 16));
    c = ((uint32)(uint16)matrix.m[1][1] | ((uint32)(uint16)matrix.m[1][2] << 16));
    d = ((uint32)(uint16)matrix.m[2][0] | ((uint32)(uint16)matrix.m[2][1] << 16));
    e = ((uint16)matrix.m[2][2]);
    SetRotMatrix(&matrix);
    game_rotate_vector_current_gte(side);
    side[0] = ((sint32)side[0] >> 2);
    side[1] = ((sint32)side[1] >> 2);
    side[2] = ((sint32)side[2] >> 2);
