uint32 game_divide_signed(uint32 numerator, uint32 denominator)
{
    if (!denominator)
        xport_mips_break(7);
    if (denominator == 0xFFFFFFFF && numerator == 0x80000000)
        xport_mips_break(6);
    return ((sint32)numerator / (sint32)denominator);
}

