void game_rotate_vector_current_gte(uint32 vector[3])
{
    uint32 high[3], low[3], mac[3], value, magnitude, index, a, b, c;
    for (index = 0; index < 3; ++index)
    {
        value = vector[index];
        magnitude = (sint32)value < 0 ? 0 - value : value;
        high[index] = ((sint32)magnitude >> 15);
        low[index] = magnitude & 0x7FFF;
        if ((sint32)value < 0)
        {
            high[index] = 0 - high[index];
            low[index] = 0 - low[index];
        }
    }
    xport_gte_write_data(9, high[0]);
    xport_gte_write_data(10, high[1]);
    xport_gte_write_data(11, high[2]);
    xport_gte_execute(0x41E012);
    mac[0] = xport_gte_read_data(25);
    mac[1] = xport_gte_read_data(26);
    mac[2] = xport_gte_read_data(27);
    xport_gte_write_data(9, low[0]);
    xport_gte_write_data(10, low[1]);
    xport_gte_write_data(11, low[2]);
    xport_gte_execute(0x49E012);
    a = xport_gte_read_data(25);
    b = xport_gte_read_data(26);
    c = xport_gte_read_data(27);
    vector[0] = a + (mac[0] << 3);
    vector[1] = b + (mac[1] << 3);
    vector[2] = c + (mac[2] << 3);
}

uint32 game_measure_direction_14(const uint32 from[3], const uint32 to[3], uint32 out[3])
{
    uint32 end, start, x, y, z, ax, ay, az, shift, length, numerator, value;
    FUNCTION_MARKER(0x80052D70, "ACE3.BIN");
    end = to[0];
    start = from[0];
    x = end - start;
    end = to[1];
    start = from[1];
    ax = (sint32)x < 0 ? 0 - x : x;
    y = end - start;
    end = to[2];
    start = from[2];
    ay = (sint32)y < 0 ? 0 - y : y;
    z = end - start;
    az = (sint32)z < 0 ? 0 - z : z;
    if ((sint32)ax < 4096 && (sint32)ay < 4096 && (sint32)az < 4096)
    {
        out[0] = 0;
        out[1] = 0;
        out[2] = 0;
        return 0;
    }
    shift = 0;
    while ((sint32)ax >= 0x4000 || (sint32)ay >= 0x4000 || (sint32)az >= 0x4000)
    {
        ++shift;
        ax = (sint32)ax >> 1;
        az = (sint32)az >> 1;
        ay = (sint32)ay >> 1;
    }
    length = game_square_root(ax * ax + ay * ay + az * az);
    x = (sint32)x >> (shift & 31);
    numerator = x << 14;
    if (length == 0)
        xport_mips_break(7);
    if (length == 0xFFFFFFFF && numerator == 0x80000000)
        xport_mips_break(6);
    value = (sint32)numerator / (sint32)length;
    y = (sint32)y >> (shift & 31);
    z = (sint32)z >> (shift & 31);
    out[0] = value;
    numerator = y << 14;
    if (length == 0)
        xport_mips_break(7);
    if (length == 0xFFFFFFFF && numerator == 0x80000000)
        xport_mips_break(6);
    value = (sint32)numerator / (sint32)length;
    out[1] = value;
    numerator = z << 14;
    if (length == 0)
        xport_mips_break(7);
    if (length == 0xFFFFFFFF && numerator == 0x80000000)
        xport_mips_break(6);
    value = (sint32)numerator / (sint32)length;
    out[2] = value;
    return length << (shift & 31);
}

void rotation_build(MATRIX *native_out, const uint16 angles[3])
{
    uint32 ax;
    uint32 ay;
    uint32 az;
    uint32 cx;
    uint32 cy;
    uint32 cz;
    uint32 sx;
    uint32 sy;
    uint32 sz;
    uint32 a;
    uint32 b;
    uint32 c;
    uint32 d;
    uint32 e;
    uint32 f;
    uint32 g;
    uint32 h;
    uint32 p;
    uint32 q;
    uint32 r;
    uint32 result;

    FUNCTION_MARKER(0x80030778, "ACE3.BIN");
    ax = angles[0];
    az = angles[2];
    ay = angles[1];
    ax &= 0x3FFF;
    az &= 0x3FFF;
    ay &= 0x3FFF;
    cx = game_wave_at((ax + 0x1000) * 2);
    cz = game_wave_at((az + 0x1000) * 2);
    sy = game_wave_at(ay * 2);
    sz = game_wave_at(az * 2);
    xport_gte_write_data(8, cx);
    xport_gte_write_data(9, sy);
    xport_gte_write_data(10, sz);
    xport_gte_write_data(11, cz);
    sx = game_wave_at(ax * 2);
    xport_gte_execute(0x190003D);
    cy = game_wave_at((ay + 0x1000) * 2);
    a = xport_gte_read_data(25);
    b = xport_gte_read_data(26);
    c = xport_gte_read_data(27);
    xport_gte_write_data(8, cy);
    xport_gte_write_data(9, sz);
    xport_gte_write_data(10, cz);
    xport_gte_write_data(11, cx);
    native_out->m[0][2] = (sint16)((sint32)a >> 16);
    xport_gte_execute(0x190003D);
    native_out->m[1][0] = (sint16)((sint32)b >> 16);
    native_out->m[1][1] = (sint16)((sint32)c >> 16);
    d = xport_gte_read_data(25);
    e = xport_gte_read_data(26);
    f = xport_gte_read_data(27);
    xport_gte_write_data(8, sy);
    xport_gte_write_data(9, cz);
    xport_gte_write_data(10, sz);
    native_out->m[2][2] = (sint16)((sint32)f >> 16);
    xport_gte_execute(0x190003D);
    native_out->m[1][2] = (sint16)((sint32)(0 - sx) >> 2);
    g = xport_gte_read_data(25);
    h = xport_gte_read_data(26);
    xport_gte_write_data(8, sx);
    xport_gte_write_data(9, (sint32)g >> 14);
    xport_gte_write_data(10, (sint32)d >> 14);
    xport_gte_write_data(11, (sint32)e >> 14);
    xport_gte_execute(0x190003D);
    p = xport_gte_read_data(25);
    q = xport_gte_read_data(26);
    r = xport_gte_read_data(27);
    xport_gte_write_data(8, sx);
    xport_gte_write_data(9, (sint32)h >> 14);
    native_out->m[0][1] = (sint16)((sint32)(p - d) >> 16);
    xport_gte_execute(0x190003D);
    native_out->m[2][0] = (sint16)((sint32)(q - g) >> 16);
    native_out->m[2][1] = (sint16)((sint32)(h + r) >> 16);
    result = xport_gte_read_data(25);
    native_out->m[0][0] = (sint16)((sint32)(e + result) >> 16);
}

void copy_words(uint32 *dst, const uint32 *src, sint32 count)
{
    sint32 i;
    uint32 value;
    FUNCTION_MARKER(0x8002759C, "ACE3.BIN");
    for (i = 0; i < count; ++i)
    {
        value = *src;
        src += 1;
        *dst = value;
        dst += 1;
    }
    return;
}

uint32 game_measure_distance_gte(const uint32 *first, const uint32 *second)
{
    uint32 x, y, z, other_x, other_y, other_z, dx, dy, dz;
    uint32 a, b, c, sum, scale, value;
    sint32 sx, sy, sz;
    FUNCTION_MARKER(0x80083DFC, "ACE3.BIN");
    x = first[0];
    y = first[1];
    z = first[2];
    other_x = second[0];
    other_y = second[1];
    other_z = second[2];
    dx = x - other_x;
    dy = y - other_y;
    dz = z - other_z;
    sx = (sint32)dx >> 12;
    sy = (sint32)dy >> 12;
    sz = (sint32)dz >> 12;
    xport_gte_write_data(9, sx);
    xport_gte_write_data(10, sy);
    xport_gte_write_data(11, sz);
    scale = 0;
    xport_gte_execute(0xA00428);
    a = sx < 0 ? 0 - (uint32)sx : (uint32)sx;
    b = sy < 0 ? 0 - (uint32)sy : (uint32)sy;
    c = sz < 0 ? 0 - (uint32)sz : (uint32)sz;
    sum = a + b + c;
    if ((sint32)sum > 0x58000)
        return 0x100000;
    if ((sint32)sum > 0xB000)
    {
        xport_gte_write_data(9, (sint32)dx >> 15);
        xport_gte_write_data(10, (sint32)dy >> 15);
        xport_gte_write_data(11, (sint32)dz >> 15);
        scale = 3;
        xport_gte_execute(0xA00428);
    }
    a = xport_gte_read_data(25);
    b = xport_gte_read_data(26);
    c = xport_gte_read_data(27);
    sum = a + b + c;
    xport_gte_write_data(30, sum);
    if ((sint32)sum <= 0)
        return 0;
    value = SquareRoot0((sint32)sum);
    return value << scale;
}
